import Testing

@testable import KMPSwiftMockableGenerator

@Suite("Mirror Generator Tests")
struct MirrorGeneratorTests {
    private let header = """
        // Generated by kmp-swift-mockable \(GeneratorVersion.current). Do not edit.

        import Foundation
        import Mockable
        import Shared

        """

    private func generate(
        _ names: [String],
        from source: String = Fixtures.shared,
        options: MirrorOptions = MirrorOptions()
    ) -> MirrorFile {
        MirrorGenerator(moduleName: "Shared", interface: ModuleInterface(source: source), options: options)
            .generate(protocolNames: names)
    }

    @Test("A mirrored parent is subclassed and every other parent is restated")
    func mirroredParentAndRestatedParents() {
        let file = generate(["UserRepository", "Repository"])
        #expect(file.missingProtocolNames.isEmpty)
        #expect(file.source == header + """

            /// Mirrors `Shared.Repository` for swift-mockable.
            @Mockable
            protocol Repository: Shared.Repository {
                func clear()
                var name: String { get }
            }

            /// Mirrors `Shared.UserRepository` for swift-mockable.
            @Mockable
            protocol UserRepository: Shared.UserRepository, Repository {
                func fetchUser(id: Int32) async throws -> Shared.User
                func findUser(name: String) async throws -> Shared.User?
                func save(users: [Shared.User])
                func save(user: Shared.User)
                var cachedUser: Shared.User? { get set }
                func close()
                func compareTo(other: Any?) -> Int32
            }

            """)
    }

    @Test("Without a mirrored parent, every parent's requirements are restated")
    func noMirroredParent() {
        let file = generate(["UserRepository"])
        #expect(file.source == header + """

            /// Mirrors `Shared.UserRepository` for swift-mockable.
            @Mockable
            protocol UserRepository: Shared.UserRepository {
                func fetchUser(id: Int32) async throws -> Shared.User
                func findUser(name: String) async throws -> Shared.User?
                func save(users: [Shared.User])
                func save(user: Shared.User)
                var cachedUser: Shared.User? { get set }
                func close()
                func compareTo(other: Any?) -> Int32
                func clear()
                var name: String { get }
            }

            """)
    }

    @Test("Only the first mirrored parent is subclassed; the others are restated without what it provides")
    func severalMirroredParents() {
        let source = """
            public protocol Named {
                var name: Swift.String { get }
            }
            public protocol Identified : Shared.Named {
                var id: Swift.Int64 { get }
            }
            public protocol Titled : Shared.Named {
                var title: Swift.String { get }
            }
            public protocol Item : Shared.Identified, Shared.Titled {
                func open()
            }
            """
        let file = generate(["Item", "Identified", "Titled"], from: source)
        #expect(file.source == header + """

            /// Mirrors `Shared.Identified` for swift-mockable.
            @Mockable
            protocol Identified: Shared.Identified {
                var id: Int64 { get }
                var name: String { get }
            }

            /// Mirrors `Shared.Titled` for swift-mockable.
            @Mockable
            protocol Titled: Shared.Titled {
                var title: String { get }
                var name: String { get }
            }

            /// Mirrors `Shared.Item` for swift-mockable.
            @Mockable
            protocol Item: Shared.Item, Identified {
                func open()
                var title: String { get }
            }

            """)
    }

    @Test("A parent the interface does not declare is dropped")
    func undeclaredParent() {
        let source = """
            public protocol Listener : ObjectiveC.NSObjectProtocol {
                func onEvent(name: Swift.String)
            }
            """
        let file = generate(["Listener"], from: source)
        #expect(file.source == header + """

            /// Mirrors `Shared.Listener` for swift-mockable.
            @Mockable
            protocol Listener: Shared.Listener {
                func onEvent(name: String)
            }

            """)
    }

    @Test("Cyclic inheritance in an invalid interface terminates")
    func cyclicInheritance() {
        let source = """
            public protocol Ping : Shared.Pong {
                func ping()
            }
            public protocol Pong : Shared.Ping {
                func pong()
            }
            """
        let file = generate(["Ping"], from: source)
        #expect(file.source.contains("""
            protocol Ping: Shared.Ping {
                func ping()
                func pong()
            }
            """))
    }

    @Test("Only the Swift qualifier is removed, including inside generic arguments")
    func removesOnlySwiftQualifier() {
        let source = """
            public protocol Cache {
                func entries() -> [Swift.String : Shared.Entry]
                func values() -> Swift.Array<Swift.Optional<Foundation.NSNumber>>
                func handler() -> ((any Swift.Error)?) -> Swift.Void
            }
            """
        let file = generate(["Cache"], from: source)
        #expect(file.source == header + """

            /// Mirrors `Shared.Cache` for swift-mockable.
            @Mockable
            protocol Cache: Shared.Cache {
                func entries() -> [String : Shared.Entry]
                func values() -> Array<Optional<Foundation.NSNumber>>
                func handler() -> ((any Error)?) -> Void
            }

            """)
    }

    @Test("The condition and access level are applied")
    func conditionAndAccessLevel() {
        let file = generate(["Repository"], options: MirrorOptions(condition: "DEBUG || TESTING", accessLevel: .public))
        #expect(file.source == header + """

            /// Mirrors `Shared.Repository` for swift-mockable.
            @Mockable(condition: "DEBUG || TESTING")
            public protocol Repository: Shared.Repository {
                func clear()
                var name: String { get }
            }

            """)
    }

    @Test("The package access level is written as a modifier")
    func packageAccessLevel() {
        let file = generate(["Closeable"], options: MirrorOptions(accessLevel: .package))
        #expect(file.source.contains("package protocol Closeable: Shared.Closeable {"))
    }

    @Test("Requested names the interface does not declare are reported, sorted")
    func missingNames() {
        let file = generate(["Zeta", "Closeable", "Alpha"])
        #expect(file.missingProtocolNames == ["Alpha", "Zeta"])
        #expect(file.source.contains("protocol Closeable: Shared.Closeable {"))
    }

    @Test("No requested protocol produces a file with the header only")
    func emptySelection() {
        let file = generate([])
        #expect(file.source == header)
    }

    @Test("The output does not depend on the order of the requested names")
    func deterministicOrder() {
        #expect(generate(["Repository", "Closeable"]) == generate(["Closeable", "Repository"]))
    }
}
